export function getG5L4PageAudioCandidate(animationId: string): G5L4PageAudioCandidate | undefined {
  return G5_L4_PAGE_AUDIO_CANDIDATES[animationId];
}

export function getG5L4FqInteractiveAudioAsset(
  language: 'en' | 'es',
  questionNumber: number,
  option: 'A' | 'B' | 'C' | 'D' | null,
): G5L4FqInteractiveAudioAsset | undefined {
  return G5_L4_FQ_INTERACTIVE_AUDIO_ASSETS.find((asset) =>
    asset.language === language &&
    asset.questionNumber === questionNumber &&
    asset.option === option
  );
}
